Timeout_Q_Node* timeout_q_free_create( void ) 
{
    Timeout_Q_Node* timeout_q_node = (Timeout_Q_Node*)os_mem_request( sizeof( struct s_Timeout_Q_Node ) ) ;

    if( timeout_q_node )
    {
        out_set( (Out)(&(timeout_q_node->timeout_q_obj)) , (Out_Func)timeout_q_execute ); 
    }

    return  timeout_q_node ; 
}

